import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

maxpool1d_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void maxpool1d_kernel(
    const float* input,
    float* output,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation,
    const int batch_size,
    const int num_features,
    const int input_seq_len,
    const int output_seq_len
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * num_features * output_seq_len;
    if (index >= total_elements) return;

    int b = index / (num_features * output_seq_len);
    int f = (index % (num_features * output_seq_len)) / output_seq_len;
    int o = index % output_seq_len;

    int start = o * stride - padding;
    float max_val = -INFINITY;

    for (int i = 0; i < kernel_size; ++i) {
        int pos = start + i * dilation;
        if (pos >= 0 && pos < input_seq_len) {
            int input_idx = b * num_features * input_seq_len + f * input_seq_len + pos;
            float val = __ldg(input + input_idx);
            max_val = fmaxf(max_val, val);
        }
    }

    int output_idx = b * num_features * output_seq_len + f * output_seq_len + o;
    output[output_idx] = max_val;
}

torch::Tensor maxpool1d_cuda(
    torch::Tensor input,
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    TORCH_CHECK(input.dim() == 3, "Input must be 3D (batch, features, sequence_length)");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous");

    int batch_size = input.size(0);
    int num_features = input.size(1);
    int input_seq_len = input.size(2);
    int output_seq_len = ((input_seq_len + 2 * padding - dilation * (kernel_size - 1) - 1) / stride) + 1;

    auto output = torch::zeros({batch_size, num_features, output_seq_len}, input.options());

    const int block_size = 256;
    int total_elements = batch_size * num_features * output_seq_len;
    int grid_size = (total_elements + block_size - 1) / block_size;

    maxpool1d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        kernel_size,
        stride,
        padding,
        dilation,
        batch_size,
        num_features,
        input_seq_len,
        output_seq_len
    );

    return output;
}
"""

maxpool1d_cpp_source = "torch::Tensor maxpool1d_cuda(torch::Tensor input, int kernel_size, int stride, int padding, int dilation);"

maxpool1d = load_inline(
    name='maxpool1d',
    cpp_sources=maxpool1d_cpp_source,
    cuda_sources=maxpool1d_source,
    functions=['maxpool1d_cuda'],
    verbose=True,
    extra_cflags=['-O3'],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0, dilation: int = 1, return_indices: bool = False):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return maxpool1d.maxpool1d_cuda(x, self.kernel_size, self.stride, self.padding, self.dilation)
